using System;
using System.Text;

namespace OfflineUnlockMod;

/// <summary>
/// Runtime-side proof gate for no-compromise custom law packets.
/// This file is generated by tools/release_port/generate_custom_law_packet_gate.py.
/// Do not hand-edit packet proof states; update custom_law_packet_proofs.json and regenerate.
/// </summary>
internal static class Homm3CustomLawPacketGate
{
	internal const string Vision = "vision";
	internal const string CommittedDamage = "committed-damage";
	internal const string Counterattack = "counterattack";
	internal const string SpellCooldown = "spell-cooldown";
	internal const string BattleAction = "battle-action";
	internal const string RewardResult = "reward-result";
	internal const string Morale = "morale";
	internal const string Construction = "construction";

	// Temporary high-risk implementation switch: enables source-prepared packet hooks for runtime testing without marking packet proofs as gameplay-proven.
	internal const bool BruteForceSourcePreparedGameplay = true;

	internal static readonly string[] KnownPackets =
	{
		Vision,
		CommittedDamage,
		Counterattack,
		SpellCooldown,
		BattleAction,
		RewardResult,
		Morale,
		Construction,
	};

	internal struct PacketProofState
	{
		internal string Packet;
		internal string ProofStatus;
		internal bool GameplayAllowed;
		internal string EvidenceSummary;
		internal string LastEvidenceArtifact;

		public override string ToString()
		{
			return "packet='" + Packet
			       + "' proofStatus='" + ProofStatus
			       + "' gameplayAllowed=" + GameplayAllowed
			       + " evidence='" + EvidenceSummary
			       + "' artifact='" + (LastEvidenceArtifact ?? "none") + "'";
		}
	}

	internal static bool TryGetPacketForLawIndex(int lawIndex, out string packet)
	{
		switch (lawIndex)
		{
			case Homm3CustomFactionLawRuntime.HeroSightRadiusIndex:
				packet = Vision;
				return true;
			case Homm3CustomFactionLawRuntime.HeroPrimaryStatTrainingIndex:
				packet = CommittedDamage;
				return true;
			case Homm3CustomFactionLawRuntime.CounterstrokeDoctrineIndex:
				packet = Counterattack;
				return true;
			case Homm3CustomFactionLawRuntime.SpellSchoolAccessLowIndex:
			case Homm3CustomFactionLawRuntime.SpellSchoolAccessHighIndex:
			case Homm3CustomFactionLawRuntime.SpellCooldownModifierIndex:
				packet = SpellCooldown;
				return true;
			case Homm3CustomFactionLawRuntime.MeleeFormationIndex:
			case Homm3CustomFactionLawRuntime.RangedFormationIndex:
				packet = BattleAction;
				return true;
			case Homm3CustomFactionLawRuntime.GoldIncomePercentIndex:
			case Homm3CustomFactionLawRuntime.AstrologyCalendarIncomeIndex:
				packet = RewardResult;
				return true;
			case Homm3CustomFactionLawRuntime.MoraleFlatIndex:
			case Homm3CustomFactionLawRuntime.MoraleTriggerIndex:
				packet = Morale;
				return true;
			case Homm3CustomFactionLawRuntime.ExtraConstructionIndex:
				packet = Construction;
				return true;
			default:
				packet = null;
				return false;
		}
	}

	internal static bool TryGetProofState(string packet, out PacketProofState state)
	{
		state = default;
		if (string.IsNullOrWhiteSpace(packet))
			return false;
		switch (packet)
		{
			case Vision:
				state = new PacketProofState
				{
					Packet = Vision,
					ProofStatus = "live-bridge-metadata-proven-reveal-mutation-unproven",
					GameplayAllowed = false,
					EvidenceSummary = "Live bridge/static metadata proves exact fog read/init/count, map-magic add/lookup, object-scouting candidates, and MapVisionObjectDesc factory identities. June 18 read-only bridge requests resolved City(Int32), Hero(Int32), Item(Int32), Method_Public_Static_MapVisionObjectDesc_Int32_PDM_0, and Method_Public_Static_MapVisionObjectDesc_String_PDM_0 with callable ordinal matches. Object classification, native fog reveal mutation, side/rank context, map refresh, and idempotent reveal semantics are not proven.",
					LastEvidenceArtifact = "experiments/cpp2il_readable_csharp/samples/latest_refresh/live_bridge_proofs",
				};
				return true;
			case CommittedDamage:
				state = new PacketProofState
				{
					Packet = CommittedDamage,
					ProofStatus = "runtime-unproven",
					GameplayAllowed = false,
					EvidenceSummary = "DiffableCs and generated interop metadata identify Hex.Session.Battle.Unit.bbgw(...) with exact generated EMechType-shaped runtime method Method_Public_Virtual_Void_InterfacePublicAbstractbaObbbUnInbbUnObbbObUnique_InterfacePublicAbstractbaBoaObVobabaObInUnique_ObjectPublicCacodaCaObceObceUnique_Int32_EMechType_Boolean_Single_Boolean_0, and a June 18 read-only bridge request returned that as the only full-signature candidate. Damage event diagnostics exist, but no decomp callable ordinal was supplied in that bridge proof, and visible committed-damage ordering, final-damage semantics, death cleanup ordering, and safe mutation semantics are not proven.",
					LastEvidenceArtifact = null,
				};
				return true;
			case Counterattack:
				state = new PacketProofState
				{
					Packet = Counterattack,
					ProofStatus = "partial-live-bridge-metadata-proven-correlation-unproven",
					GameplayAllowed = false,
					EvidenceSummary = "Live bridge metadata proves exact dxx resolver-set and ebv listener-set candidates for diagnostics, but real counterattack dispatch, actor identity, committed damage correlation, Focus/buff/restore mutation, and active law-rank consumption are not proven.",
					LastEvidenceArtifact = "experiments/cpp2il_readable_csharp/samples/latest_refresh/live_bridge_proofs",
				};
				return true;
			case SpellCooldown:
				state = new PacketProofState
				{
					Packet = SpellCooldown,
					ProofStatus = "live-bridge-metadata-proven-cast-gate-unproven",
					GameplayAllowed = false,
					EvidenceSummary = "Live bridge metadata proves exact effective/decrement/add-if-ready/pool-shift cooldown candidates. A June 18 read-only resolve_decomp_method request for eew.bdmh(Int32) / decomp ordinal 45 rejected the shape-only generated Void(Int32) candidates: ordinal 45 resolved to Method_Private_Single_Int32_PDM_4, while generated Void(Int32) methods were ordinal mismatches. setCooldown remains unpromoted; source-prepared cooldown reductions now use repeated exact decrement calls instead of an absolute setter. Cast-gate/UI/execution synchronization and active law-rank consumption are not proven.",
					LastEvidenceArtifact = "experiments/cpp2il_readable_csharp/samples/latest_refresh/live_bridge_proofs",
				};
				return true;
			case BattleAction:
				state = new PacketProofState
				{
					Packet = BattleAction,
					ProofStatus = "runtime-unproven",
					GameplayAllowed = false,
					EvidenceSummary = "Diagnostic battle-event and formationProbe surfaces exist, but visible melee/ranged/first-action/adjacency correlation and active law-rank consumption are not proven.",
					LastEvidenceArtifact = null,
				};
				return true;
			case RewardResult:
				state = new PacketProofState
				{
					Packet = RewardResult,
					ProofStatus = "partial-live-bridge-metadata-proven-commit-unproven",
					GameplayAllowed = false,
					EvidenceSummary = "Live bridge metadata proves exact reward queue/remove candidates and resource data mutation semantics. A June 18 read-only resolve for czy.vji(Hero,DataRewardSet) found Method_Public_Void_Hero_DataRewardSet_PDM_0 as the full-shape candidate but with callable ordinal 36, while requested decomp ordinal 37 resolved to a mismatched Void(Int32) method; reward apply therefore remains unbound. Committed reward/result source identity, idempotent grant point, and active law-rank consumption are not proven.",
					LastEvidenceArtifact = "experiments/cpp2il_readable_csharp/samples/latest_refresh/live_bridge_proofs",
				};
				return true;
			case Morale:
				state = new PacketProofState
				{
					Packet = Morale,
					ProofStatus = "runtime-unproven",
					GameplayAllowed = false,
					EvidenceSummary = "Morale roll diagnostics exist, but visible extra-action/failure ordering, action queue mutation, and active law-rank consumption are not proven.",
					LastEvidenceArtifact = null,
				};
				return true;
			case Construction:
				state = new PacketProofState
				{
					Packet = Construction,
					ProofStatus = "live-bridge-metadata-proven-runtime-ordering-unproven",
					GameplayAllowed = false,
					EvidenceSummary = "Live bridge metadata proves exact runtime candidates for construction UI/session/building-data surfaces, including Hex.Session.City.BhBuildingsManager.bajt(String) resolving to Method_Private_MonoBehaviourPublicStBhbuceBhInceStBhceUnique_String_PDM_0 with callable ordinal match. Displayed cost, charged cost, eligibility, build commit, resource mutation, constructed state, and active law-rank agreement are not proven.",
