	}

	internal static bool IsGameplayAllowed(string packet, out string failReason)
	{
		if (!TryGetProofState(packet, out var state))
		{
			failReason = "unknown custom law packet '" + (packet ?? "null") + "'";
			return false;
		}
		if (BruteForceSourcePreparedGameplay && IsBruteForcePacketAllowed(state.Packet))
		{
			failReason = null;
			return true;
		}
		if (!state.GameplayAllowed)
		{
			failReason = "packet '" + state.Packet + "' is " + state.ProofStatus + "; " + state.EvidenceSummary;
			return false;
		}
		failReason = null;
		return true;
	}


	internal static bool IsBruteForcePacketAllowed(string packet)
	{
		switch (packet)
		{
			case CommittedDamage:
			case Counterattack:
			case SpellCooldown:
			case BattleAction:
			case RewardResult:
			case Morale:
				return true;
			case Vision:
			case Construction:
			default:
				return false;
		}
	}

	internal static bool IsLawIndexGameplayAllowed(int lawIndex, out string packet, out string failReason)
	{
		if (!TryGetPacketForLawIndex(lawIndex, out packet))
		{
			failReason = "law index " + lawIndex.ToString(System.Globalization.CultureInfo.InvariantCulture) + " has no no-compromise packet mapping";
			return false;
		}
		return IsGameplayAllowed(packet, out failReason);
	}

	internal static string DescribeKnownProofStates()
	{
		var sb = new StringBuilder();
		for (var i = 0; i < KnownPackets.Length; i++)
		{
			if (i > 0)
				sb.Append("; ");
			if (TryGetProofState(KnownPackets[i], out var state))
				sb.Append(state);
			else
				sb.Append("packet='").Append(KnownPackets[i]).Append("' proofState=missing");
		}
		return sb.ToString();
	}
}
